style.css:
/* Fondo de la página con los colores de Doraemon */
body {
    background-color: #00A9E0; /* Azul de Doraemon */
    color: white; /* Texto blanco para contrastar */
    font-family: 'Arial', sans-serif;
}

/* Cambiar los títulos h1 y h2 para que se vean como Doraemon */
h1, h2 {
    color: #F5B800; /* Amarillo de Doraemon */
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.6);
    font-family: 'Comic Sans MS', cursive, sans-serif;
}

/* Agregar una cara de Doraemon como imagen de fondo (opcional) */
body {
    background-image: url('https://example.com/doraemon_face.png'); /* URL de la imagen de Doraemon */
    background-size: cover;
    background-position: center;
}

/* Personalizar los enlaces con colores de Doraemon */
a {
    color: #FF5F00; /* Naranja de Doraemon */
    text-decoration: none;
}

a:hover {
    color: #F5B800; /* Amarillo cuando el enlace está en hover */
}

/* Personalizar botones con un estilo de Doraemon */
button {
    background-color: #00A9E0; /* Azul de Doraemon */
    color: white;
    border: 2px solid #F5B800;
    border-radius: 10px;
    padding: 10px 20px;
    font-size: 16px;
}

button:hover {
    background-color: #F5B800;
    color: #00A9E0;
}
